macro.command:
// Amellwind unified rune controller (Foundry v12 / dnd5e 4.4 / MidiQOL + DAE + Item Macro)
// DAE runs this via change key "macro.itemMacro": args[0] === "on" when equipped, "off" when unequipped.
// MidiQOL on-use passes arrive with args[0].macroPass (registered by the cloned effect on the actor).
const FLAG = "amellwind-toolbox";
// Foundry only allows getFlag/setFlag for active module ids / "world" / "core".
// This content pack uses a custom namespace, so read/write via getProperty + update.
const getRuneFlag = (doc, key) => foundry.utils.getProperty(doc, `flags.${FLAG}.${key}`);
const setRuneFlag = async (doc, key, value) => doc.update({ [`flags.${FLAG}.${key}`]: value });
const unsetRuneFlag = async (doc, key) => doc.update({ [`flags.${FLAG}.-=${key}`]: null });
const actorDoc = actor ?? item?.actor ?? item?.parent;
if (!item) return;
const arg0 = args?.[0];
const pass = String(arg0?.macroPass ?? "").toLowerCase();
const runeName = getRuneFlag(item, "runeName") ?? item.name;

async function runeCleanup() {
  if (!actorDoc) return;
  const mine = actorDoc.effects.filter((e) => getRuneFlag(e, "runeClone") && e.origin === item.uuid);
  if (mine.length) await actorDoc.deleteEmbeddedDocuments("ActiveEffect", mine.map((e) => e.id));
  await unsetRuneFlag(item, "applied");
}

function runeAeName(side, matName, trinket) {
  let n = `${runeName}-${side}`;
  if (matName) n += `-${matName}`;
  if (trinket) n += " (Trinket)";
  return n;
}

async function runeApplySide(side, trinket) {
  if (!actorDoc) return;
  const blueprints = item.effects.filter((e) => getRuneFlag(e, "runeSide") === side);
  const docs = blueprints.map((e) => {
    const o = e.toObject();
    delete o._id;
    o.origin = item.uuid;
    o.disabled = false;
    o.transfer = false;
    o.name = runeAeName(side, getRuneFlag(e, "materialEffectName"), trinket);
    foundry.utils.setProperty(o, `flags.${FLAG}.runeClone`, true);
    // Never clutter the token with rune status icons (many runes equipped at once).
    foundry.utils.setProperty(o, "flags.dae.showIcon", false);
    return o;
  });
  if (docs.length) await actorDoc.createEmbeddedDocuments("ActiveEffect", docs);
  await setRuneFlag(item, "applied", { side, trinket });
  if (typeof runeOnEquip === "function") await runeOnEquip(side, trinket);
}

if (arg0 === "on") {
  if (!actorDoc) return;
  await runeCleanup();
  const sides = getRuneFlag(item, "sides") ?? {};
  const available = Object.keys(sides).filter((s) => sides[s]);
  if (!available.length) return;
  const radios = available
    .map((s, i) => `<label style="display:block;margin:.15rem 0"><input type="radio" name="runeSide" value="${s}" ${i === 0 ? "checked" : ""}/> ${sides[s].label ?? s}</label>`)
    .join("");
  const content = `<form class="dnd5e2"><p>Choose which effect to activate for <strong>${runeName}</strong>:</p>${radios}<hr/><label style="display:block;margin-top:.35rem"><input type="checkbox" name="runeTrinket"/> Equipped in a trinket</label></form>`;
  const choice = await new Promise((resolve) => {
    new Dialog({
      title: `${runeName} Rune`,
      content,
      buttons: {
        ok: { icon: '<i class="fas fa-check"></i>', label: "Activate", callback: (html) => resolve({ side: html.find('input[name="runeSide"]:checked').val(), trinket: html.find('input[name="runeTrinket"]').is(":checked") }) },
        cancel: { icon: '<i class="fas fa-times"></i>', label: "Cancel", callback: () => resolve(null) },
      },
      default: "ok",
      close: () => resolve(null),
    }).render(true);
  });
  if (!choice || !choice.side) { await item.update({ "system.equipped": false }); return; }
  await runeApplySide(choice.side, choice.trinket);
  return;
}

if (arg0 === "off") { await runeCleanup(); return; }
if (arg0 === "each") return;

// ===== rune-specific combat passes =====
// Stamina Drain: on weapon hit, apply the item's blueprint AE to each hit target.
if (pass.includes("postdamageroll") || pass.includes("postactiveeffects")) {
  const wf = workflow ?? arg0?.workflow;
  if (!wf) return;

  const itemType = String(wf.item?.type ?? "").toLowerCase();
  const actType = String(wf.activity?.type ?? arg0?.activity?.type ?? "").toLowerCase();
  const actionType = String(arg0?.itemActionType ?? wf.itemActionType ?? "").toLowerCase();
  const isWeaponAttack =
    itemType === "weapon"
    || ["mwak", "rwak"].includes(actionType)
    || (actType === "attack" && itemType !== "spell");
  if (!isWeaponAttack) return;

  const hits = [...(arg0?.hitTargets ?? wf.hitTargets ?? [])];
  if (!hits.length) return;

  if (wf.amellwindStaminaDrainApplied) return;
  wf.amellwindStaminaDrainApplied = true;

  const blueprint = item.effects.find((e) => getRuneFlag(e, "staminaDrainBlueprint") === true)
    ?? item.effects.find((e) => /stamina drain/i.test(e.name ?? "") && !getRuneFlag(e, "runeSide"));

  const origin = actorDoc?.uuid ?? item.uuid;
  const img = blueprint?.img ?? item?.img ?? "icons/svg/aura.svg";

  const buildEffect = () => {
    if (blueprint) {
      const o = blueprint.toObject();
      delete o._id;
      o.disabled = false;
      o.transfer = false;
      o.origin = origin;
      if (!o.system) o.system = {};
      foundry.utils.setProperty(o, "flags.dae.showIcon", true);
      foundry.utils.setProperty(o, "flags.dae.specialDuration", ["turnStartSource"]);
      foundry.utils.setProperty(o, "flags.dae.stackable", "noneName");
      foundry.utils.setProperty(o, `flags.${FLAG}.staminaDrain`, true);
      if (o.flags?.[FLAG]?.staminaDrainBlueprint != null) delete o.flags[FLAG].staminaDrainBlueprint;
      return o;
    }
    return {
      name: "Stamina Drain (-5 ft)",
      img,
      type: "base",
      system: {},
      origin,
      transfer: false,
      disabled: false,
      duration: { turns: 1, rounds: null, seconds: null, startTime: null, combat: null, startRound: null, startTurn: null },
      changes: [
        { key: "system.attributes.movement.walk", mode: 2, value: "-5", priority: 20 },
        { key: "system.attributes.movement.fly", mode: 2, value: "-5", priority: 20 },
        { key: "system.attributes.movement.swim", mode: 2, value: "-5", priority: 20 },
        { key: "system.attributes.movement.climb", mode: 2, value: "-5", priority: 20 },
        { key: "system.attributes.movement.burrow", mode: 2, value: "-5", priority: 20 },
      ],
      statuses: [],
      tint: "#ffffff",
      description: "Speed reduced by 5 feet until the start of the attacker's next turn.",
      flags: {
        dae: { specialDuration: ["turnStartSource"], stackable: "noneName", showIcon: true },
        [FLAG]: { staminaDrain: true },
      },
    };
  };

  const resolveActor = (t) =>
    t?.actor ?? t?.document?.actor ?? (t?.documentName === "Actor" ? t : null);

  const applyTo = async (targetActor, docs) => {
    if (typeof MidiQOL?.socket === "function" && !game.user.isGM) {
      try {
        await MidiQOL.socket().executeAsGM("createEffects", {
          actorUuid: targetActor.uuid,
          effects: docs,
        });
        return;
      } catch (err) {
        console.warn("Stamina Drain createEffects via Midi socket failed", err);
      }
    }
    await targetActor.createEmbeddedDocuments("ActiveEffect", docs);
  };

  const removeFrom = async (targetActor, ids) => {
    if (!ids.length) return;
    if (typeof MidiQOL?.socket === "function" && !game.user.isGM) {
      try {
        await MidiQOL.socket().executeAsGM("removeEffects", {
          actorUuid: targetActor.uuid,
          effects: ids.map((id) => targetActor.effects.get(id)?.uuid).filter(Boolean),
        });
        return;
      } catch (err) {
        console.warn("Stamina Drain removeEffects via Midi socket failed", err);
      }
    }
    await targetActor.deleteEmbeddedDocuments("ActiveEffect", ids);
  };

  for (const t of hits) {
    const targetActor = resolveActor(t);
    if (!targetActor) continue;
    const stale = targetActor.effects.filter(
      (ef) =>
        foundry.utils.getProperty(ef, `flags.${FLAG}.staminaDrain`) === true
        || /stamina drain/i.test(ef.name ?? ""),
    );
    if (stale.length) await removeFrom(targetActor, stale.map((e) => e.id));
    await applyTo(targetActor, [buildEffect()]);
  }
  return;
}
